package lab.enterprise;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;
import org.springframework.expression.spel.standard.SpelExpressionParser;import org.springframework.expression.spel.support.SimpleEvaluationContext;import org.springframework.expression.common.TemplateParserContext;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.net.*;import java.io.*;import javax.xml.parsers.*;import javax.xml.XMLConstants;import javax.xml.xpath.*;import org.xml.sax.InputSource;
/** Deliberately bounded local diagnostic fixtures. No external callback hosts or arbitrary commands. */
@RestController public final class AdaptiveLabController {
 private final Path root=Path.of(System.getProperty("java.io.tmpdir"),"payload-runner-fixtures").toAbsolutePath().normalize(),allowed=root.resolve("allowed");
 public AdaptiveLabController()throws IOException{Files.createDirectories(allowed);Files.writeString(allowed.resolve("base.txt"),"NORMAL_ALLOWED_FILE");Files.writeString(root.resolve("download-marker.txt"),"PR_OWNED_XML_FIXTURE");}
 private boolean fixed(String mode){if(!mode.equals("vuln")&&!mode.equals("fixed"))throw new IllegalArgumentException("mode");return mode.equals("fixed");}
 @GetMapping(value="/api/adaptive/{mode}/expression",produces="text/plain") public String expression(@PathVariable("mode")String mode,@RequestParam(name="q",defaultValue="alpha")String q){if(fixed(mode))return q;try{return Objects.toString(new SpelExpressionParser().parseExpression(q,new TemplateParserContext()).getValue(SimpleEvaluationContext.forReadOnlyDataBinding().build()),"");}catch(Exception e){return "expression rejected";}}
 @GetMapping(value="/api/adaptive/{mode}/file",produces="text/plain") public ResponseEntity<String> file(@PathVariable("mode")String mode,@RequestParam(name="q",defaultValue="base.txt")String q){try{Path path=allowed.resolve(q).normalize();if(!path.startsWith(root)||fixed(mode)&&!path.startsWith(allowed))return ResponseEntity.status(404).body("file not found");return ResponseEntity.ok(Files.readString(path));}catch(Exception e){return ResponseEntity.status(404).body("file not found");}}
 @GetMapping(value="/api/adaptive/{mode}/ssrf",produces="text/plain") public String ssrf(@PathVariable("mode")String mode,@RequestParam(name="q",defaultValue="alpha")String q){if(!fixed(mode)&&q.matches("http://127\\.0\\.0\\.1:19112/pr/PR_[0-9a-f]{16}")){try{var conn=new URL(q).openConnection();conn.setConnectTimeout(1500);conn.setReadTimeout(1500);try(var in=conn.getInputStream()){in.readNBytes(256);}}catch(Exception ignored){}}return "accepted";}
 @GetMapping(value="/api/adaptive/{mode}/command",produces="text/plain") public String command(@PathVariable("mode")String mode,@RequestParam(name="q",defaultValue="alpha")String q){if(!fixed(mode)&&q.matches("alpha(?:;|\\|)printf 'PR_(?:CMD|CTRL)_%s' 'PR_[0-9a-f]{16}'(?:;)?")){try{var process=new ProcessBuilder("sh","-c",q).start();if(!process.waitFor(2,java.util.concurrent.TimeUnit.SECONDS)){process.destroyForcibly();return "command timed out";}return new String(process.getInputStream().readNBytes(2048),StandardCharsets.UTF_8);}catch(Exception e){return "command unavailable";}}return "normal";}
 @PostMapping(value="/api/adaptive/{mode}/xml",produces="text/plain") public ResponseEntity<String> xml(@PathVariable("mode")String mode,@RequestBody String xml){try{if(xml.contains("file:")&&!xml.contains(root.toUri().toString()))return ResponseEntity.badRequest().body("outside owned fixture");var f=DocumentBuilderFactory.newInstance();boolean blocked=fixed(mode);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",blocked);f.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,blocked?"":"file");f.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");var parser=f.newDocumentBuilder();parser.setErrorHandler(new org.xml.sax.helpers.DefaultHandler());return ResponseEntity.ok(parser.parse(new InputSource(new StringReader(xml))).getDocumentElement().getTextContent());}catch(Exception e){return ResponseEntity.badRequest().body("XML rejected");}}
 @GetMapping(value="/api/adaptive/{mode}/xpath",produces="text/plain") public String xpath(@PathVariable("mode")String mode,@RequestParam(name="q",defaultValue="alpha")String q){if(fixed(mode))return q.equals("alpha")?"rows=1":"rows=0";try{var doc=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new InputSource(new StringReader("<users><user><name>alpha</name></user><user><name>beta</name></user></users>")));return "rows="+XPathFactory.newInstance().newXPath().evaluate("count(/users/user[name='"+q+"'])",doc);}catch(Exception e){return "XPathExpressionException: invalid predicate";}}
 @GetMapping(value="/adaptive-lab",produces="text/html;charset=UTF-8") public String page(){return "<!doctype html><meta charset='utf-8'><h1>커뮤니티 적응형 진단 실습</h1><p>로컬 테스트 전용 · vuln/fixed 쌍으로 비교하세요.</p><table border='1' cellpadding='8'><tr><th>유형</th><th>경로</th><th>기준</th></tr><tr><td>Spring 표현식</td><td>/api/adaptive/vuln/expression?q=입력</td><td>alpha / #{731*919}</td></tr><tr><td>파일 경로</td><td>/api/adaptive/vuln/file?q=입력</td><td>base.txt / ../download-marker.txt</td></tr><tr><td>HTTP SSRF</td><td>/api/adaptive/vuln/ssrf?q=입력</td><td>alpha / 확장의 콜백 포트 19112</td></tr><tr><td>명령 출력</td><td>/api/adaptive/vuln/command?q=입력</td><td>alpha / 제한된 printf 진단문만 허용</td></tr><tr><td>XML</td><td>POST /api/adaptive/vuln/xml</td><td>&lt;r&gt;alpha&lt;/r&gt; / 소유한 파일 엔티티</td></tr><tr><td>XPath</td><td>/api/adaptive/vuln/xpath?q=입력</td><td>alpha / 진단 조건·따옴표</td></tr></table><p>vuln을 fixed로 바꾸면 대응 처리를 비교할 수 있습니다. SSRF는 응답을 항상 accepted로 반환하므로 콜백으로만 서버 요청을 확인합니다. 파일은 실습 전용 폴더만 읽으며, 명령은 제한된 printf만 허용합니다.</p><p><a href='/community'>커뮤니티</a> · <a href='/extensions'>확장 실습</a></p>";}
}
